.darma-loader-darma-b13-fingerprint-scan { --accent: var(--loader-color, #22d3ee); --accent-2: var(--loader-secondary-color, #334155); width: calc(var(--loader-size, 116px) * .74); height: calc(var(--loader-size, 116px) * .88); position: relative; overflow: hidden; border-radius: 46% 46% 40% 40%; background: repeating-radial-gradient(circle at 50% 64%, transparent 0 6.5%, var(--accent-2) 6.5% 9%); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 14%, var(--accent-2)); }
.darma-loader-darma-b13-fingerprint-scan::after { content: ''; position: absolute; inset: 0; background: var(--accent); animation: darma-loader-darma-b13-fingerprint-scan-verify calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b13-fingerprint-scan span { position: absolute; z-index: 2; left: 0; width: 100%; height: 9%; background: linear-gradient(transparent, var(--accent), transparent); box-shadow: 0 0 calc(var(--loader-size, 116px) * .09) var(--accent); animation: darma-loader-darma-b13-fingerprint-scan-fscan calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
@keyframes darma-loader-darma-b13-fingerprint-scan-fscan { 0% { top: -9%; } 50% { top: 100%; } 100% { top: -9%; } }
@keyframes darma-loader-darma-b13-fingerprint-scan-verify { 0%, 42% { opacity: 0; } 52% { opacity: .3; } 68%, 100% { opacity: 0; } }

